def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    cr = sum(r for r, c in points) / len(points)
    cc = sum(c for r, c in points) / len(points)
    out = [row[:] for row in grid]

    for color in counts:
        if color == bg:
            continue
        for dr, dc in ((1, 1), (1, -1)):
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != color:
                        continue
                    pr, pc = r - dr, c - dc
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                        continue
                    run = []
                    rr, cc2 = r, c
                    while 0 <= rr < h and 0 <= cc2 < w and grid[rr][cc2] == color:
                        run.append((rr, cc2))
                        rr += dr
                        cc2 += dc
                    if len(run) < 2:
                        continue
                    a, b = run[0], run[-1]
                    da = (a[0] - cr) ** 2 + (a[1] - cc) ** 2
                    db = (b[0] - cr) ** 2 + (b[1] - cc) ** 2
                    if da > db or (da == db and a[0] <= b[0]):
                        er, ec, sr, sc = a[0], a[1], -dr, -dc
                    else:
                        er, ec, sr, sc = b[0], b[1], dr, dc
                    rr, cc2 = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc2 < w and out[rr][cc2] == bg:
                        out[rr][cc2] = color
                        rr += sr
                        cc2 += sc
    return out
